#!/usr/bin/env python3
"""Generates ../trade-drift.repl (run by sync-fixtures.sh): partial fills whose cost rounds UP the
most (each taker pays <1 unit extra, to the maker) push the remaining price below the posted one
until a minimum-size fill would cost under 100 units — the point where its fee would round to
nothing. The suite then asserts the contract REFUSES that fill, still takes a larger one with a
fee, and still closes. Python picks amounts only; trade computes and the REPL asserts."""
import os
import math
from fractions import Fraction as F
P = "n_48867b242317a0216a67f8c7ca26696b5878e0e3.trade"
A = "a1" * 32; B_ = "b0" * 32
def ceil_p(x, p):
    q = 10 ** p; return F(math.ceil(x * q), q)
def floor_p(x, p):
    q = 10 ** p; return F(math.floor(x * q), q)
def fmt(x, p):
    n = x * 10 ** p; assert n.denominator == 1; n = n.numerator
    ip, fp = divmod(n, 10 ** p); return f"{ip}.{str(fp).rjust(p, '0')}"
sp, bp = 6, 2
S, B, mt = F(100), F(100), F(1)   # mt: the piece size a taker keeps asking for (1.0 TOK6 = 100 units of TOK2 at the posted price)
sr, br = S, B
o = [";; EVERY-PARTIAL-FILL-PAYS-A-FEE — GENERATED by fixtures/make-drift-test.py, never hand-edited.",
     ";; An order is filled in the pieces that round up the most until a minimum-size fill would cost",
     ";; under 100 smallest units (its 1 % fee would round to nothing). That fill is refused; a larger",
     ";; one and the closing one still work.",
     '(load "setup.repl")', "(env-exec-config [])",
     '(begin-tx "create: sell 100 tok6 for 100.00 tok2, a 1.0 piece costs 100 units, fee 1 unit")', f"(use {P})",
     f'(env-data {{ "bob-g": {{ "keys": ["{B_}"], "pred": "keys-all" }} }})',
     f'(env-sigs [{{ "key": "{B_}", "caps": [(n_bro.tok6.TRANSFER tn.BOB (tn.esc tn.BOB "D") 100.0) (PLACE (tn.key tn.BOB "D"))] }}])',
     '(create-order "D" tn.BOB (read-keyset "bob-g") n_bro.tok6 100.0 n_bro.tok2 100.0 0.05)',
     '(expect "at posting a 1.0 piece pays a 0.01 fee" 0.01 (at \'maker-fee (quote (tn.key tn.BOB "D") 1.0)))',
     "(commit-tx)"]
n = 0
while True:
    # find a >= mt (leaving something), maximising the round-up
    best, bo = None, F(-1)
    a = mt
    for _ in range(3000):
        if sr - a <= 0: break
        ex = a * br / sr; ov = ceil_p(ex, bp) - ex
        if ov > bo: best, bo = a, ov
        a += F(1, 10 ** sp)
    if best is None: break
    # stop once a 1.0 piece would cost under 100 units, i.e. carry no fee
    if ceil_p(mt * br / sr, bp) < F(1): break
    cost = ceil_p(best * br / sr, bp)
    n += 1
    o += [f'(begin-tx "fill {n}")', f"(use {P})", f'(env-data {{ "alice-g": {{ "keys": ["{A}"], "pred": "keys-all" }} }})',
          f'(let ((q (quote (tn.key tn.BOB "D") {fmt(best, sp)}))) (env-sigs [{{ "key": "{A}", "caps": [(n_bro.tok2.TRANSFER tn.ALICE tn.BOB (at \'maker-net q)) (n_bro.tok2.TRANSFER tn.ALICE tn.SINK (at \'maker-fee q))] }}]))',
          f'(expect "fill {n} pays its exact cost and fee" [{fmt(cost, bp)} {fmt(floor_p(cost / 100, bp), bp)}] (let ((f (fill-order (tn.key tn.BOB "D") tn.ALICE (read-keyset "alice-g") {fmt(best, sp)} 0.05))) [(at \'cost f) (at \'maker-fee f)]))', "(commit-tx)"]
    sr, br = sr - best, br - cost
rest = fmt(sr, sp)
bigger = fmt(mt * 2, sp)
K = '(tn.key tn.BOB "D")'
o += ['(begin-tx "the price of the remainder has drifted")', f"(use {P})",
      f'(expect "maker has received at least the posted ratio for what was taken" true (>= (- 100.0 (at \'buy-remaining (get-order {K}))) (- 100.0 (at \'sell-remaining (get-order {K})))))',
      f'(expect-failure "EVERY-PARTIAL-FILL-PAYS-A-FEE: a minimum-size fill would now cost under 100 units" "Fill is too small: its cost is below 100 smallest units of the buy token" (quote {K} 1.0))',
      f'(expect "a larger partial fill is accepted and carries a fee" true (> (at \'maker-fee (quote {K} {bigger})) 0.0))',
      f'(expect "the closing fill is accepted" true (at \'closes (quote {K} {rest})))',
      "(commit-tx)"]
open(os.environ.get("DRIFT_OUT") or os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "trade-drift.repl"), "w").write("\n".join(o) + "\n"); print("drift suite: fills", n)
